"""Build a public catalogue without publishing paid files or legacy demo APIs."""
import json, re, shutil
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'public'
source=(ROOT/'docs/framework/10_Pillars_Framework.md').read_text()
items=[]
for n,title,body in re.findall(r'### Pillar (\d+): ([^\n]+)\n(.*?)(?=\n### |\n---)',source,re.S):
 points=[s[2:] for s in body.splitlines() if s.startswith('- ')]
 slug=re.sub(r'[^a-z0-9]+','-',title.lower()).strip('-')
 items.append(dict(number=int(n),title=title,slug=slug,points=points,checkout_enabled=False))
assert len(items)==10
if OUT.exists(): shutil.rmtree(OUT)
OUT.mkdir()
style=(ROOT/'site_assets/style.css').read_text()
shutil.copytree(ROOT/'site_assets',OUT/'assets')
def page(title,body,path):
 target=OUT/path;target.parent.mkdir(parents=True,exist_ok=True)
 target.write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} · Major AI Mindset</title><meta name="description" content="Explore the ten pillars of Major AI Mindset. Practical learning for Caribbean communities, creators and builders everywhere."><meta name="theme-color" content="#030304"><link rel="icon" href="/assets/md-medallion.png"><link rel="preload" as="image" href="/assets/caribbean.png"><link rel="stylesheet" href="/style.css"></head><body><a class="skip" href="#content">Skip to content</a><header><a class="brand" href="/" aria-label="Ten Pillars home"><img src="/assets/md-medallion.png" width="64" height="64" alt="Major Dream crown seal"><span>MAJOR AI MINDSET<small>THE TEN PILLARS</small></span></a><nav aria-label="Main"><a href="/#pillars">The pillars</a><a href="/series/">The collection</a><a class="parent-link" href="https://www.majoraimindset.com">Enter MAIM <span aria-hidden="true">↗</span></a></nav></header><main id="content">{body}</main><footer><div class="footer-brand"><img src="/assets/md-medallion.png" width="76" height="76" alt="Major Dream crown seal"><p>Major AI Mindset<small>AI is the tool. You are the future.</small></p></div><div><a href="https://www.majoraimindset.com">Return to MAIM ↗</a><br><a href="mailto:contact@majoraimindset.com">Contact</a><p class="fine">Major Dream Williams · The Ten Pillars</p></div></footer></body></html>''')
(OUT/'style.css').write_text(style)
cards=''.join(f'<article class="pillar-row"><span class="num">{p["number"]:02}</span><div><h3><a href="/pillars/{p["slug"]}/">{escape(p["title"])}</a></h3><p>{escape(p["points"][0])}</p></div><a class="row-arrow" href="/pillars/{p["slug"]}/" aria-label="Explore {escape(p["title"])}">↗</a></article>' for p in items)
page('The Ten Pillars',f'''<section class="hero home-hero"><div class="coast" aria-hidden="true"></div><div class="hero-copy"><div class="eyebrow"><span class="signal"></span> ROOTED IN CULTURE. BUILT FOR WHAT’S NEXT.</div><h1>Own your mindset.<br><em>Build your legacy.</em></h1><p class="intro">Ten pillars. One connected way forward. Bring timeless wisdom and emerging technology into your life, your work, and your community.</p><div class="actions"><a class="button" href="#pillars">Explore the ten pillars <span aria-hidden="true">↗</span></a><a class="text-link" href="/series/">Discover the collection <span aria-hidden="true">→</span></a></div></div><div class="hero-seal" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><img src="/assets/md-medallion.png" width="300" height="300" alt=""><span class="seal-caption">WISDOM · CULTURE · POSSIBILITY</span></div><div class="hero-bottom"><span>CARIBBEAN ROOTS. GLOBAL REACH.</span><a href="#story">A Major way of thinking <span aria-hidden="true">↓</span></a></div></section><section id="story" class="story scene"><div class="eyebrow">THE HUMAN IS THE HERO</div><div><h2>Your roots are strength.<br><em>Your future is yours to shape.</em></h2><p class="note">For the Caribbean diaspora and builders everywhere, progress begins with what you already carry: your culture, your curiosity, and your lived experience. MAIM connects that foundation to practical ways of learning, creating, and using technology with purpose.</p><div class="tribar" aria-hidden="true"><i></i><i></i><i></i></div></div></section><section id="pillars" class="scene"><div class="section-heading"><div><div class="eyebrow">THE FRAMEWORK</div><h2>Find your<br><em>starting point.</em></h2></div><p class="note">Begin where life is asking you to grow.<br>Every pillar connects to the next.</p></div><div class="pillar-index">{cards}</div></section><section class="practice scene"><div><div class="eyebrow">KNOWLEDGE BECOMES CAPABILITY</div><h2>Read. Reflect.<br><em>Make a Major Move.</em></h2><p class="note">You don’t have to change everything today.<br>Likkle by likkle, we build the future.</p></div><ol class="practice-list"><li><span>01</span><div><h3>Read with intention.</h3><p>Explore a principle that matters in your life today.</p></div></li><li><span>02</span><div><h3>Make it personal.</h3><p>Connect it to your situation, family, and community.</p></div></li><li><span>03</span><div><h3>Take one useful step.</h3><p>Put the idea to work. Notice what changes.</p></div></li></ol></section><section class="collection scene"><div class="eyebrow">THE MAIM COLLECTION</div><h2>One pillar can open a door.<br><em>Ten can change the view.</em></h2><p class="note">Explore individual pillars or the connected framework. Individual e-book editions and the complete-series option are in preparation.</p><a class="button" href="/series/">Explore the collection <span aria-hidden="true">↗</span></a><p class="fine">Purchasing opens when editions, pricing, and secure delivery are ready.</p></section>''',Path('index.html'))
for p in items:
 bullets=''.join('<li>'+escape(s)+'</li>' for s in p['points'])
 page(p['title'],f'''<section class="hero"><div class="eyebrow">PILLAR {p['number']:02} / THE TEN PILLARS</div><h1>{escape(p['title'])}</h1><p class="intro">{escape(p['points'][0])}</p></section><div class="grid"><section class="card"><h2>Explore the ideas</h2><ul>{bullets}</ul><h3>Your reflection</h3><p>Where could this pillar make a difference in your life or community? Write down one small step you can take.</p></section><aside class="card"><div class="eyebrow">INDIVIDUAL E-BOOK</div><h2>Start with this pillar.</h2><p class="status">Edition in preparation · Purchasing not yet available</p><p>The individual edition, price and secure delivery are being finalized.</p><a class="button secondary" href="/series/">Compare with the full series</a></aside></div><section class="band"><a href="/#pillars">← Explore all ten pillars</a></section>''',Path('pillars')/p['slug']/'index.html')
page('The Complete Series','''<section class="hero"><div class="eyebrow">THE MAIM TEN PILLARS SERIES</div><h1>A connected framework.<br>A journey of your own.</h1><p class="intro">Explore identity, resilience, learning, ownership, community and legacy through all ten pillars.</p></section><section class="card"><h2>The complete-series option</h2><p>Choose the whole collection or begin with the pillar most relevant to you.</p><p class="status">Collection in preparation · Purchasing not yet available</p><p>Final contents, editions and pricing will be shown here before checkout opens.</p><a class="button" href="/#pillars">Browse the ten pillars</a></section><section class="band"><h2>Continue your MAIM journey</h2><p class="note">Begin with Awareness, Belief and Context, then explore the principles that help you apply technology with purpose.</p><a class="button secondary" href="https://www.majoraimindset.com">Explore Major AI Mindset ↗</a></section>''',Path('series/index.html'))
(OUT/'catalog.json').write_text(json.dumps(dict(pillars=items,series=dict(checkout_enabled=False)),indent=2))
(OUT/'health.json').write_text(json.dumps(dict(status='ok',service='maim-pillars-catalog',checkout='disabled')))
print(json.dumps(dict(event='catalog_build',pillars=len(items),pages=12,paid_assets_published=False)))
